#!/usr/bin/env bash
set -euo pipefail

log() {
  printf '%s %s\n' "$(date -Is)" "$*" >&2
}

copier() {
  local source="$1" dest="$2"
  if [ ! -d "$source" ]; then
    log "Source absente : $source"
    return 1
  fi
  cp -r -- "$source" "$dest"
}

